declare
  v_project public.natori_projects%rowtype;
  v_task_count integer;
  v_expected_count integer;
  v_matching_count integer;
begin
  if p_type is null
     or p_type not in ('icon', 'sd', 'standing', 'illustration')
  then
    return query select 'invalid_type'::text, null::uuid, null::text, 0;
    return;
  end if;

  select projects.*
  into v_project
  from public.natori_projects as projects
  where projects.id = p_project_id
    and projects.user_id = p_user_id
    and projects.deleted_at is null
  for update;

  if not found then
    return query select 'not_found'::text, null::uuid, null::text, 0;
    return;
  end if;

  select count(*)::integer
  into v_task_count
  from public.natori_project_tasks as tasks
  where tasks.project_id = v_project.id;

  select count(*)::integer
  into v_expected_count
  from public.natori_project_task_template_v1(p_type);

  select count(*)::integer
  into v_matching_count
  from public.natori_project_tasks as tasks
  join public.natori_project_task_template_v1(p_type) as template
    on template.task_key = tasks.task_key
   and template.label = tasks.label
   and template.stage = tasks.stage
   and template.estimated_hours is not distinct from tasks.estimated_hours
   and template.done is not distinct from tasks.done
   and template.sort_order = tasks.sort_order
  where tasks.project_id = v_project.id;

  if v_project.status not in (
       'inquiry', 'estimating', 'consulting', 'quoted', 'awaiting_payment'
     )
     or v_project.payment_confirmed_at is not null
  then
    return query select 'conflict'::text, v_project.id, v_project.type, v_task_count;
    return;
  end if;

  if v_project.type = p_type
     and v_task_count = v_expected_count
     and v_matching_count = v_expected_count
  then
    return query select
      'already_confirmed'::text,
      v_project.id,
      v_project.type,
      v_task_count;
    return;
  end if;

  if v_project.type <> 'undecided' or v_task_count <> 0 then
    return query select 'conflict'::text, v_project.id, v_project.type, v_task_count;
    return;
  end if;

  update public.natori_projects as projects
  set type = p_type,
      updated_at = now()
  where projects.id = v_project.id;

  insert into public.natori_project_tasks (
    project_id, task_key, label, stage, estimated_hours, done, sort_order
  )
  select
    v_project.id,
    template.task_key,
    template.label,
    template.stage,
    template.estimated_hours,
    template.done,
    template.sort_order
  from public.natori_project_task_template_v1(p_type) as template;

  get diagnostics v_task_count = row_count;
  return query select 'confirmed'::text, v_project.id, p_type, v_task_count;
end;

declare
  v_created_at timestamptz;
  v_file jsonb;
  v_path text;
  v_link jsonb;
  v_request_label text;
  v_title text;
  v_next_action text;
begin
  if p_user_id is null
     or not exists (
       select 1 from auth.users as users where users.id = p_user_id
     )
  then
    raise exception using errcode = '22023', message = 'invalid_owner';
  end if;

  if p_project_id is null then
    raise exception using errcode = '22023', message = 'project_id_required';
  end if;

  if not public.natori_request_text_is_valid_v1(p_client_name, 100, 1) then
    raise exception using errcode = '22023', message = 'invalid_client_name';
  end if;

  if not public.natori_request_text_is_valid_v1(p_client_email, 254, 1)
     or p_client_email like '.%'
     or p_client_email like '%..%'
     or p_client_email !~ '^[A-Za-z0-9_''+.-]*[A-Za-z0-9_+-]@([A-Za-z0-9][A-Za-z0-9-]*\.)+[A-Za-z]{2,}$'
  then
    raise exception using errcode = '22023', message = 'invalid_client_email';
  end if;

  if not public.natori_request_data_is_valid_v1(p_request_data) then
    raise exception using errcode = '22023', message = 'invalid_request_data';
  end if;

  if p_reference_files is null
     or jsonb_typeof(p_reference_files) <> 'array'
     or jsonb_array_length(p_reference_files) > 5
     or (
       select count(*) <> count(distinct files.value #>> '{}')
       from jsonb_array_elements(p_reference_files) as files(value)
     )
  then
    raise exception using errcode = '22023', message = 'invalid_reference_files';
  end if;

  for v_file in
    select files.value
    from jsonb_array_elements(p_reference_files) as files(value)
  loop
    if jsonb_typeof(v_file) <> 'string' then
      raise exception using errcode = '22023', message = 'invalid_reference_file';
    end if;
    v_path := v_file #>> '{}';
    if v_path !~ (
      '^' || p_project_id::text ||
      '/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\.webp$'
    ) then
      raise exception using errcode = '22023', message = 'reference_file_scope_mismatch';
    end if;
    if not exists (
      select 1
      from storage.objects as objects
      where objects.bucket_id = 'natori-inquiry-refs'
        and objects.name = v_path
    ) then
      raise exception using errcode = '22023', message = 'reference_file_not_found';
    end if;
    if exists (
      select 1
      from public.natori_inquiry_reference_files as reference_files
      join public.natori_projects as existing_projects
        on existing_projects.id = reference_files.project_id
      where reference_files.storage_path = v_path
        and reference_files.project_id <> p_project_id
    ) then
      raise exception using errcode = '23505', message = 'reference_file_already_linked';
    end if;
  end loop;

  if p_reference_links is null
     or jsonb_typeof(p_reference_links) <> 'array'
     or jsonb_array_length(p_reference_links) > 5
  then
    raise exception using errcode = '22023', message = 'invalid_reference_links';
  end if;

  for v_link in
    select links.value
    from jsonb_array_elements(p_reference_links) as links(value)
  loop
    if not public.natori_jsonb_has_exact_keys_v1(
      v_link,
      array['url', 'normalized_url', 'label', 'provider', 'sort_order']::text[]
    )
       or jsonb_typeof(v_link -> 'url') <> 'string'
       or jsonb_typeof(v_link -> 'normalized_url') <> 'string'
       or not public.natori_request_text_is_valid_v1(v_link ->> 'url', 2048, 1)
       or not public.natori_request_text_is_valid_v1(v_link ->> 'normalized_url', 2048, 1)
       or lower(left(v_link ->> 'url', 8)) <> 'https://'
       or left(v_link ->> 'normalized_url', 8) <> 'https://'
       or position('#' in (v_link ->> 'normalized_url')) > 0
       or substring(v_link ->> 'url' from '^.{8}([^/?#]+)') is null
       or position('@' in substring(v_link ->> 'url' from '^.{8}([^/?#]+)')) > 0
       or substring(v_link ->> 'normalized_url' from '^https://([^/?#]+)') is null
       or position('@' in substring(v_link ->> 'normalized_url' from '^https://([^/?#]+)')) > 0
       or substring(v_link ->> 'normalized_url' from '^https://([^/?#]+)')
          <> lower(substring(v_link ->> 'normalized_url' from '^https://([^/?#]+)'))
       or substring(v_link ->> 'normalized_url' from '^https://([^/?#]+)') ~ ':443$'
       or jsonb_typeof(v_link -> 'sort_order') <> 'number'
       or mod((v_link ->> 'sort_order')::numeric, 1) <> 0
       or (v_link ->> 'sort_order')::numeric < 0
       or (v_link ->> 'sort_order')::numeric > 2147483647
    then
      raise exception using errcode = '22023', message = 'invalid_reference_link';
    end if;

    if v_link -> 'label' = 'null'::jsonb then
      null;
    elsif jsonb_typeof(v_link -> 'label') <> 'string'
       or not public.natori_request_text_is_valid_v1(v_link ->> 'label', 100, 0)
    then
      raise exception using errcode = '22023', message = 'invalid_reference_link_label';
    end if;

    if v_link -> 'provider' = 'null'::jsonb then
      null;
    elsif jsonb_typeof(v_link -> 'provider') <> 'string'
       or not public.natori_request_text_is_valid_v1(v_link ->> 'provider', 50, 0)
    then
      raise exception using errcode = '22023', message = 'invalid_reference_link_provider';
    end if;
  end loop;

  if (
    select count(*) <> count(distinct links.value ->> 'normalized_url')
    from jsonb_array_elements(p_reference_links) as links(value)
  ) then
    raise exception using errcode = '23505', message = 'duplicate_reference_link';
  end if;

  v_request_label := case p_request_data ->> 'requestType'
    when 'undecided' then '未定・相談して決めたい'
    when 'icon' then 'SNSアイコン'
    when 'sd' then 'SDキャラクター'
    when 'standing' then '立ち絵'
    when 'illustration' then '一枚絵'
    when 'other' then p_request_data ->> 'requestTypeOther'
  end;
  if p_request_data -> 'legacySource' <> 'null'::jsonb
     and char_length(p_request_data #>> '{legacySource,requestTypeLabel}') > 0
  then
    v_request_label := p_request_data #>> '{legacySource,requestTypeLabel}';
  end if;
  v_title := v_request_label || ' / ' || p_client_name;
  v_next_action := case p_request_data ->> 'inquiryMode'
    when 'consultation' then '相談内容を確認'
    when 'quote' then '内容確認・案件種別を確定'
  end;

  insert into public.natori_projects (
    id, user_id, title, client_name, client_email, amount, type, status,
    delivery_plan, priority, start_date, due_date, next_action, note,
    request_data, deleted_at
  ) values (
    p_project_id, p_user_id, v_title, p_client_name, p_client_email, null,
    'undecided', 'inquiry', 'normal', null, null, null, v_next_action,
    null, p_request_data, null
  )
  on conflict (id) do nothing
  returning natori_projects.created_at into v_created_at;

  if found then
    insert into public.natori_inquiry_reference_files (project_id, storage_path)
    select p_project_id, files.value #>> '{}'
    from jsonb_array_elements(p_reference_files) as files(value);

    insert into public.natori_project_reference_links (
      project_id, url, normalized_url, label, provider, sort_order
    )
    select
      p_project_id,
      links.value ->> 'url',
      links.value ->> 'normalized_url',
      case when links.value -> 'label' = 'null'::jsonb then null else links.value ->> 'label' end,
      case when links.value -> 'provider' = 'null'::jsonb then null else links.value ->> 'provider' end,
      (links.value ->> 'sort_order')::integer
    from jsonb_array_elements(p_reference_links) as links(value);
  else
    select projects.created_at
    into v_created_at
    from public.natori_projects as projects
    where projects.id = p_project_id
      and projects.user_id = p_user_id
      and projects.title = v_title
      and projects.client_name = p_client_name
      and projects.client_email is not distinct from p_client_email
      and projects.amount is null
      and projects.type = 'undecided'
      and projects.status = 'inquiry'
      and projects.delivery_plan = 'normal'
      and projects.priority is null
      and projects.start_date is null
      and projects.due_date is null
      and projects.next_action = v_next_action
      and projects.note is null
      and projects.request_data = p_request_data
      and projects.payment_confirmed_at is null
      and projects.payment_link_id is null
      and projects.quoted_amount is null
      and projects.quote_accept_token_hash is null
      and projects.quote_token_expires_at is null
      and projects.quote_accepted_at is null
      and projects.quote_accepted_amount is null
      and projects.delivery_token_hash is null
      and projects.delivery_token_expires_at is null
      and projects.delivered_mail_at is null
      and projects.delivery_accepted_at is null
      and projects.active_quote_id is null
      and projects.payment_quote_id is null
      and projects.payment_link_url is null
      and projects.payment_link_status is null
      and projects.paid_amount is null
      and projects.stripe_payment_session_id is null
      and projects.paid_at is null
      and projects.completed_at is null
      and projects.deleted_at is null
      and not exists (
        select 1 from public.natori_project_tasks as tasks
        where tasks.project_id = projects.id
      )
      and (
        select count(*) from public.natori_inquiry_reference_files as reference_files
        where reference_files.project_id = projects.id
      ) = jsonb_array_length(p_reference_files)
      and not exists (
        select 1 from jsonb_array_elements(p_reference_files) as files(value)
        where not exists (
          select 1 from public.natori_inquiry_reference_files as reference_files
          where reference_files.project_id = projects.id
            and reference_files.storage_path = files.value #>> '{}'
        )
      )
      and (
        select count(*) from public.natori_project_reference_links as reference_links
        where reference_links.project_id = projects.id
      ) = jsonb_array_length(p_reference_links)
      and not exists (
        select 1 from jsonb_array_elements(p_reference_links) as links(value)
        where not exists (
          select 1 from public.natori_project_reference_links as reference_links
          where reference_links.project_id = projects.id
            and reference_links.url = links.value ->> 'url'
            and reference_links.normalized_url = links.value ->> 'normalized_url'
            and reference_links.label is not distinct from case
              when links.value -> 'label' = 'null'::jsonb then null
              else links.value ->> 'label'
            end
            and reference_links.provider is not distinct from case
              when links.value -> 'provider' = 'null'::jsonb then null
              else links.value ->> 'provider'
            end
            and reference_links.sort_order = (links.value ->> 'sort_order')::integer
        )
      )
    for update of projects;

    if not found then
      raise exception using errcode = '23505', message = 'submission_conflict';
    end if;
  end if;

  return query select p_project_id, v_created_at;
end;

declare
  v_deleted uuid;
begin
  delete from public.natori_projects
  where id = p_project_id and user_id = p_user_id
  returning id into v_deleted;
  return v_deleted is not null;
end;

declare
  v_project public.natori_projects%rowtype;
  v_existing public.natori_quotes%rowtype;
  v_quote_id uuid;
  v_version integer;
  v_item_total bigint;
  v_invalid_item_count integer;
  v_unresolved_review_count integer;
  v_orphan_resolution_count integer;
  v_total_text text;
  v_now timestamptz := now();
begin
  if p_user_id is null or p_project_id is null then
    raise exception 'owner_and_project_required';
  end if;
  if nullif(trim(p_title), '') is null
     or nullif(trim(p_client_name), '') is null
     or nullif(trim(p_to_email), '') is null
     or nullif(trim(p_subject), '') is null
     or nullif(trim(p_body_snapshot), '') is null
     or nullif(trim(p_token_hash), '') is null then
    raise exception 'quote_fields_required';
  end if;
  if p_amount is null or p_amount <= 0 then raise exception 'invalid_quote_amount'; end if;
  if p_expires_at is null or p_expires_at <= v_now then raise exception 'invalid_quote_expiry'; end if;
  if p_idempotency_key is null
     or char_length(p_idempotency_key) not between 8 and 200
     or p_idempotency_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' then
    raise exception 'invalid_idempotency_key';
  end if;
  if p_request_snapshot is not null then
    if jsonb_typeof(p_request_snapshot) <> 'object'
       or p_request_snapshot->>'schemaVersion' <> '1' then
      raise exception 'invalid_request_snapshot';
    end if;
  end if;
  if jsonb_typeof(p_pricing_snapshot) <> 'object'
     or p_pricing_snapshot->>'schemaVersion' <> '1'
     or p_pricing_snapshot->>'currency' <> 'JPY' then
    raise exception 'invalid_pricing_snapshot';
  end if;
  if jsonb_typeof(p_pricing_snapshot->'items') <> 'array'
     or jsonb_array_length(p_pricing_snapshot->'items') = 0 then
    raise exception 'quote_items_required';
  end if;
  if jsonb_typeof(p_pricing_snapshot->'reviewItems') <> 'array'
     or jsonb_typeof(p_pricing_snapshot->'reviewResolutions') <> 'array' then
    raise exception 'invalid_review_snapshot';
  end if;

  if jsonb_typeof(p_pricing_snapshot->'total') <> 'number' then
    raise exception 'invalid_pricing_snapshot';
  end if;
  v_total_text := p_pricing_snapshot->>'total';
  if v_total_text !~ '^[0-9]+$'
     or char_length(v_total_text) > 10
     or v_total_text::numeric > 2147483647 then
    raise exception 'invalid_pricing_snapshot';
  end if;
  if v_total_text::integer <> p_amount then raise exception 'quote_total_mismatch'; end if;

  select count(*) into v_invalid_item_count
  from jsonb_array_elements(p_pricing_snapshot->'items') as item
  where jsonb_typeof(item) <> 'object'
     or jsonb_typeof(item->'quantity') <> 'number'
     or jsonb_typeof(item->'unitAmount') <> 'number'
     or jsonb_typeof(item->'amount') <> 'number'
     or coalesce(item->>'quantity', '') !~ '^[0-9]+$'
     or coalesce(item->>'unitAmount', '') !~ '^[0-9]+$'
     or coalesce(item->>'amount', '') !~ '^[0-9]+$'
     or char_length(coalesce(item->>'quantity', '')) > 3
     or char_length(coalesce(item->>'unitAmount', '')) > 10
     or char_length(coalesce(item->>'amount', '')) > 10;

  if v_invalid_item_count > 0 then raise exception 'invalid_quote_item'; end if;

  select
    coalesce(sum((item->>'amount')::bigint), 0),
    count(*) filter (
      where (item->>'quantity')::integer not between 1 and 100
         or (item->>'unitAmount')::numeric > 2147483647
         or (item->>'amount')::numeric > 2147483647
         or (item->>'amount')::numeric <> (item->>'unitAmount')::numeric * (item->>'quantity')::numeric
    )
  into v_item_total, v_invalid_item_count
  from jsonb_array_elements(p_pricing_snapshot->'items') as item;

  if v_invalid_item_count > 0 then raise exception 'invalid_quote_item'; end if;
  if v_item_total <> p_amount then raise exception 'quote_item_total_mismatch'; end if;

  select count(*) into v_unresolved_review_count
  from jsonb_array_elements(p_pricing_snapshot->'reviewItems') as review_item
  where not exists (
    select 1
    from jsonb_array_elements(p_pricing_snapshot->'reviewResolutions') as resolution
    where resolution->>'code' = review_item->>'code'
      and resolution->>'ruleId' = review_item->>'ruleId'
      and resolution->>'resolution' in ('accepted', 'overridden', 'not_applicable')
  );
  if v_unresolved_review_count > 0 then raise exception 'unresolved_review_item'; end if;

  select count(*) into v_orphan_resolution_count
  from jsonb_array_elements(p_pricing_snapshot->'reviewResolutions') as resolution
  where not exists (
    select 1
    from jsonb_array_elements(p_pricing_snapshot->'reviewItems') as review_item
    where review_item->>'code' = resolution->>'code'
      and review_item->>'ruleId' = resolution->>'ruleId'
  );
  if v_orphan_resolution_count > 0 then raise exception 'orphan_review_resolution'; end if;

  select * into v_project
  from public.natori_projects
  where id = p_project_id and user_id = p_user_id
  for update;

  if not found then raise exception 'project_not_found'; end if;
  if v_project.deleted_at is not null then raise exception 'project_archived'; end if;
  if v_project.payment_confirmed_at is not null then raise exception 'project_already_paid'; end if;
  if v_project.type = 'undecided' then raise exception 'project_type_undecided'; end if;
  if v_project.status not in ('inquiry', 'consulting', 'estimating', 'quoted') then raise exception 'invalid_quote_state'; end if;
  if p_pricing_snapshot->>'projectTypeSnapshot' <> v_project.type then raise exception 'project_type_snapshot_mismatch'; end if;
  if p_request_snapshot is distinct from v_project.request_data then raise exception 'request_snapshot_mismatch'; end if;

  select * into v_existing
  from public.natori_quotes
  where project_id = p_project_id and idempotency_key = p_idempotency_key;

  if found then
    if v_existing.user_id is distinct from p_user_id
       or v_existing.title is distinct from p_title
       or v_existing.client_name is distinct from p_client_name
       or v_existing.to_email is distinct from p_to_email
       or v_existing.amount is distinct from p_amount
       or v_existing.subject is distinct from p_subject
       or v_existing.body_snapshot is distinct from p_body_snapshot
       or v_existing.token_hash is distinct from p_token_hash
       or v_existing.expires_at is distinct from p_expires_at
       or v_existing.request_snapshot is distinct from p_request_snapshot
       or v_existing.pricing_snapshot is distinct from p_pricing_snapshot then
      raise exception 'idempotency_conflict';
    end if;
    return query select v_existing.id, v_existing.version, true;
    return;
  end if;

  update public.natori_quotes
  set superseded_at = coalesce(superseded_at, v_now)
  where project_id = p_project_id and superseded_at is null;

  select coalesce(max(q.version), 0) + 1 into v_version
  from public.natori_quotes q where q.project_id = p_project_id;

  insert into public.natori_quotes (
    project_id, user_id, version, title, client_name, to_email, amount,
    subject, body_snapshot, token_hash, expires_at, request_snapshot,
    pricing_snapshot, idempotency_key, issued_at
  ) values (
    p_project_id, p_user_id, v_version, p_title, p_client_name, p_to_email,
    p_amount, p_subject, p_body_snapshot, p_token_hash, p_expires_at,
    p_request_snapshot, p_pricing_snapshot, p_idempotency_key, v_now
  ) returning id into v_quote_id;

  update public.natori_projects
  set active_quote_id = v_quote_id,
      client_email = p_to_email,
      amount = p_amount,
      quoted_amount = p_amount,
      quote_accept_token_hash = p_token_hash,
      quote_token_expires_at = p_expires_at,
      quote_accepted_at = null,
      quote_accepted_amount = null
  where id = p_project_id and user_id = p_user_id;

  return query select v_quote_id, v_version, false;
end;
